-- 20. create trigger to prevent negative discount
CREATE TRIGGER prevent_negative_discount BEFORE
INSERT ON orders FOR EACH ROW BEGIN IF NEW.discount < 0 THEN
Set new.discount = 0;
END IF;
END;
insert into orders
values (
    1014,
    231,
    138,
    '2024-01-03',
    500.00,
    -20.00,
    'UPI',
    20
  );
select *
from orders
where order_id = 1014;
-- 21. delivery delay warning table
CREATE TABLE delivery_delay_warnings (
  warning_id INT PRIMARY KEY AUTO_INCREMENT,
  order_id INT,
  customer_id INT,
  restaurant_id INT,
  delivery_time INT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
create trigger log_delivery_delay
AFTER
INSERT ON orders FOR EACH ROW BEGIN IF NEW.delivery_time > 45 THEN
INSERT INTO delivery_delay_warnings (
    order_id,
    customer_id,
    restaurant_id,
    delivery_time
  )
VALUES (
    NEW.order_id,
    NEW.customer_id,
    NEW.restaurant_id,
    NEW.delivery_time
  );
END IF;
END;
